Check Mini-Project Prior to Submission
When you are about ready to submit a mini-project, the following script can be used to make sure all relevant files have been uploaded. In particular, it verifies that the source mp0N.qmd and the rendered docs/mp0N.html files are on GitHub, then it also checks for the css, js and image files, alerting if these cannot be loaded. Note that this check is only ‘first-order’ (so a css imported by another css file will not be verified) but this is enough to catch most problems.

mp_submission_ready &lt;- function(N, github_id){
    if(!require("yaml")) install.packages("yaml"); library(yaml)
    if(!require("gh")) install.packages("gh"); library(gh)
    if(!require("tidyverse")) install.packages("tidyverse"); library(tidyverse)
    if(!require("rvest")) install.packages("rvest"); library(rvest)
    if(!require("glue")) install.packages("glue"); library(glue)
    if(!require("httr2")) install.packages("httr2"); library(httr2)  

    if(missing(N)){
        N &lt;- menu(title="Which Mini-Project would you like to check was properly submitted on GitHub?", 
                  choices=c(0, 1, 2, 3, 4))
    }

    mp_url &lt;- glue("https://michael-weylandt.com/STA9750/mini/mini0{N}.html")

    mp_text &lt;- read_html(mp_url) |&gt; html_element("#submission-text") |&gt; html_text()

    if(missing(github_id)){
        github_id &lt;- readline("What is your GitHub ID? ")
    }

    variables &lt;- read_yaml("https://raw.githubusercontent.com/michaelweylandt/STA9750/refs/heads/main/_variables.yml")
    course_repo  &lt;- variables$course$repo
    course_short &lt;- variables$course$short

    BASE_URL &lt;- glue("https://{github_id}.github.io/{course_repo}/")

    page_resp &lt;- request(BASE_URL) |&gt;
        req_url_path_append(glue("mp0{N}.html")) |&gt;
        req_error(is_error = \(r) FALSE) |&gt; 
        req_perform()

    if(resp_is_error(page_resp)){
        stop(glue("I was unable to access your submission at {page_resp$url}. Please make sure that your content has been successfully uploaded to GitHub."))
    }

    cat(glue("I was able to access your submission at {page_resp$url}, now checking JS and CSS files."), "\n")

    SUPPORT_FILES &lt;- page_resp |&gt; resp_body_html() |&gt; html_elements("link") |&gt; html_attr("href")

    SUPPORT_STATUS &lt;- map_lgl(SUPPORT_FILES, function(s){
        supp_resp_error &lt;- request(BASE_URL) |&gt; 
            req_url_path_append(s) |&gt;
            req_error(is_error = \(r) FALSE) |&gt;
            req_perform() |&gt;
            resp_is_error()

        if(supp_resp_error){
            cat(glue("- I could not find the file {s} that your site attempts to load.\n  Please make sure docs/{s} has been uploaded via Git to your GitHub.\n"))
            cat("\n")
        }
        !supp_resp_error
    }) 

    if(!all(SUPPORT_STATUS)){
        stop("Necessary support files could not be verified. Please visually inspect all elements of your site before submission.")
        browseURL(page_resp$url)
    }

    IMAGE_FILES &lt;- page_resp |&gt; resp_body_html() |&gt; html_elements("img") |&gt; html_attr("src")

    IMAGE_STATUS &lt;- map_lgl(IMAGE_FILES, function(s){
        img_resp_error &lt;- request(BASE_URL) |&gt; 
            req_url_path_append(s) |&gt;
            req_error(is_error = \(r) FALSE) |&gt;
            req_perform() |&gt;
            resp_is_error()

        if(img_resp_error){
            cat(glue("- I could not find the image file {s} that your site attempts to load.\n  Please make sure docs/{s} has been uploaded via Git to your GitHub.\n"))
            cat("\n")
        }
        !img_resp_error
    }) 

    if(!all(IMAGE_STATUS)){
        stop("Necessary image files could not be verified. Please visually inspect all elements of your site before submission.")
        browseURL(page_resp$url)
    }

    if(N == 0){
        raw_url &lt;- glue("https://raw.githubusercontent.com/{github_id}/{course_repo}/refs/heads/main/index.qmd")
    } else {
        raw_url &lt;- glue("https://raw.githubusercontent.com/{github_id}/{course_repo}/refs/heads/main/mp0{N}.qmd")
    }

    resp_raw &lt;- request(raw_url) |&gt; 
        req_error(is_error = \(r) FALSE) |&gt;
        req_perform()

    if(resp_is_error(resp_raw)){
        ## Try again with 'master' instead of 'main' branch
        raw_url_master &lt;- str_replace(raw_url, "main", "master")
        resp_raw &lt;- request(raw_url_master) |&gt; 
            req_error(is_error = \(r) FALSE) |&gt;
            req_perform()
    }

    if(resp_is_error(resp_raw)){
        cat("I cannot find the source qmd document at", raw_url, "or", 
            raw_url_master, ".\n",
            "Please confirm it was correctly submitted and try again.\n",
            "This document is needed for automated code quality checks.\n")

        stop("Miniproject not ready for submission.")
    }

    cat("Congratulations! Your mini-project appears to be ready for submission!\n")
    cat("Visually verify it one more time before submission.\n")
    cat("Then run the following command to submit on GitHub.\n")
    cat("\n")
    cat(glue('source("https://michael-weylandt.com/STA9750/load_helpers.R"); mp_submission_create(N={N}, github_id="{github_id}")'), "\n")
    cat("Then upload a PDF of your submission to Brightspace.\n")
    invisible(TRUE)
}

Submit Mini-Project via GitHub Issue
The following function will create the GitHub issue necessary to submit a mini-project:

mp_submission_create &lt;- function(N, github_id){
    if(!require("yaml")) install.packages("yaml"); library(yaml)
    if(!require("gh")) install.packages("gh"); library(gh)
    if(!require("tidyverse")) install.packages("tidyverse"); library(tidyverse)
    if(!require("rvest")) install.packages("rvest"); library(rvest)
    if(!require("glue")) install.packages("glue"); library(glue)
    if(!require("httr2")) install.packages("httr2"); library(httr2)

    if(missing(N)){
        N &lt;- menu(title="Which Mini-Project would you like to submit on GitHub?", 
                  choices=c(0, 1, 2, 3, 4))
    }

    mp_url &lt;- glue("https://michael-weylandt.com/STA9750/mini/mini0{N}.html")

    mp_text &lt;- read_html(mp_url) |&gt; html_element("#submission-text") |&gt; html_text()

    if(missing(github_id)){
        github_id &lt;- readline("What is your GitHub ID? ")
    }

    variables &lt;- read_yaml("https://raw.githubusercontent.com/michaelweylandt/STA9750/refs/heads/main/_variables.yml")
    course_repo  &lt;- variables$course$repo
    course_short &lt;- variables$course$short

    title &lt;- glue("{course_short} {github_id} MiniProject #0{N}")

    body &lt;- mp_text |&gt; str_replace("YOUR_GITHUB_ID", github_id) |&gt; str_trim()

    r &lt;- request("https://github.com/") |&gt;
        req_url_path_append("michaelweylandt") |&gt;
        req_url_path_append(course_repo) |&gt;
        req_url_path_append("issues/new") |&gt;
        req_url_query(title=title, 
                      body=body) 

    browseURL(r$url)
}

Verify Mini-Project Submission
The following function will confirm that the submission issue is properly formatted.

mp_submission_verify &lt;- function(N, github_id){
    if(!require("yaml")) install.packages("yaml"); library(yaml)
    if(!require("gh")) install.packages("gh"); library(gh)
    if(!require("tidyverse")) install.packages("tidyverse"); library(tidyverse)
    if(!require("rvest")) install.packages("rvest"); library(rvest)
    if(!require("glue")) install.packages("glue"); library(glue)
    if(!require("httr2")) install.packages("httr2"); library(httr2)  

    if(missing(N)){
        N &lt;- menu(title="Which Mini-Project would you like to check was properly submitted on GitHub?", 
                  choices=c(0, 1, 2, 3, 4))
    }

    mp_url &lt;- glue("https://michael-weylandt.com/STA9750/mini/mini0{N}.html")

    mp_text &lt;- read_html(mp_url) |&gt; html_element("#submission-text") |&gt; html_text()

    if(missing(github_id)){
        github_id &lt;- readline("What is your GitHub ID? ")
    }

    variables &lt;- read_yaml("https://raw.githubusercontent.com/michaelweylandt/STA9750/refs/heads/main/_variables.yml")
    course_repo  &lt;- variables$course$repo
    course_short &lt;- variables$course$short

    title &lt;- glue("{course_short} {github_id} MiniProject #0{N}")

    body &lt;- mp_text |&gt; str_replace("YOUR_GITHUB_ID", github_id) |&gt; str_squish()

    page &lt;- 1

    issues &lt;- list()

    while((length(issues) %% 100) == 0){
        new_issues &lt;- gh("/repos/michaelweylandt/{repo}/issues?state=all&per_page=100&page={page}", 
                         repo=course_repo, 
                         page=page)

        if(length(new_issues) == 0){
            break
        }

        issues &lt;- c(issues, new_issues)
        page &lt;- page + 1
    }

    issue_names &lt;- vapply(issues, function(x) str_squish(x$title), "")

    name_match &lt;- which(issue_names == title)
    case_insensitive_match &lt;- which(tolower(issue_names) == tolower(title))

    if((length(name_match) == 0) & (length(case_insensitive_match) == 0)){
        cat("I could not find a unique issue with the title:\n", 
            "    ", sQuote(title),"\n",
            "The issues I found had the following titles:\n",
            paste(c("", issue_names), collapse="\n - "), "\n",
            "If something on that list looks correct, please check",
            "capitalization and punctuation.\n")
        stop("MINIPROJECT NOT SUBMITTED CORRECTLY.")
    } else if((length(name_match) == 0) & (length(case_insensitive_match) &gt;= 0)) {
        cat("I have found a partial match (differing by case only).\n",
            "- Searching for: ", title, , "\n", 
            "- Found: ", issue_names[case_insensitive_match], ".\n",
            "Attempting to proceed with partial match issue")
        name_match &lt;- case_insensitive_match
    } else if(length(name_match) &gt; 1){
        cat("I found multiple issues with the title:\n", 
            "    ", sQuote(title),"\n",
            "Please change the names of issues so that there is only", 
            "issue with the desired name. (Note that closing an issue is",
            "not sufficient.)\n")

        stop("MINIPROJECT NOT SUBMITTED CORRECTLY.")
    }

    issue &lt;- issues[[name_match]]

    issue_num &lt;- issue$number
    issue_url &lt;- issue$html_url
    issue_body &lt;- issue$body |&gt; str_squish()

    cat("Identified Issue #", issue_num, "at", issue_url, "as possible candidate.\n")

    if(issue$state != "open"){
        cat("Issue does not appear to be in 'open' status. Please",
            "confirm the issue is open and try again.\n")
        stop("MINIPROJECT NOT SUBMITTED CORRECTLY.")
    }

    if(!str_equal(issue_body, body, ignore_case = TRUE)){
        cat("Issue does not appear to exactly match the correct body text.",
            "This is not necessarily an issue since the expected link is present",
            "but you may want to confirm all relevant",
            "information is included.\n")
    }

    # This isn't quite general enough, but I think it covers everything
    # we'll see in this course. 
    URL_REGEX &lt;- "http[A-Za-z0-9:/\\-\\.]*"

    urls &lt;- str_match_all(paste(issue_body, "\n Thanks!\n", sep=""), 
                          URL_REGEX)[[1]] |&gt; unique()
    expected_url &lt;- str_extract(body, URL_REGEX)

    if(length(urls) &gt; 1){
        cat("The following URLs were found in the issue text:",
            paste(c("", urls), collapse="\n - "), 
            "Only one URL was expected; please remove any extras.\n")
        stop("MINIPROJECT NOT SUBMITTED CORRECTLY.")
    }

    submitted_url &lt;- urls[1]

    if(!str_equal(submitted_url, expected_url, ignore_case = TRUE)){
        cat("The submitted URL does not match the Mini-Project instructions.\n", 
            "Expected:\n - ", expected_url, "\n", 
            "Submitted:\n - ", submitted_url, "\n", 
            "Please correct any differences and try again.\n")
        stop("MINIPROJECT NOT SUBMITTED CORRECTLY.")
    }

    resp &lt;- request(submitted_url) |&gt; 
        req_error(is_error = \(r) FALSE) |&gt;
        req_perform()

    if(resp_is_error(resp)){
        cat("Something appears to be incorrect at the URL: ", 
            submitted_url, 
            "\n Please confirm that it is working as expected and try again.")
        browseURL(submitted_url)
        stop("MINIPROJECT NOT SUBMITTED SUCCESSFULLY.")
    }

    if(N == 0){
        raw_url &lt;- glue("https://raw.githubusercontent.com/{github_id}/{course_repo}/refs/heads/main/index.qmd")
    } else {
        raw_url &lt;- glue("https://raw.githubusercontent.com/{github_id}/{course_repo}/refs/heads/main/mp0{N}.qmd")
    }

    resp_raw &lt;- request(raw_url) |&gt; 
        req_error(is_error = \(r) FALSE) |&gt;
        req_perform()

    if(resp_is_error(resp_raw)){
        ## Try again with 'master' instead of 'main' branch
        raw_url_master &lt;- str_replace(raw_url, "main", "master")
        resp_raw &lt;- request(raw_url_master) |&gt; 
            req_error(is_error = \(r) FALSE) |&gt;
            req_perform()
    }

    if(resp_is_error(resp_raw)){
        cat("I cannot find the source qmd document at", raw_url, "or", 
            raw_url_master, ".\n",
            "Please confirm it was correctly submitted and try again.\n",
            "This document is needed for automated code quality checks.\n")

        stop("MINIPROJECT NOT SUBMITTED SUCCESSFULLY.")
    }

    cat("Congratulations! Your mini-project appears to have been submitted correctly!\n")
    invisible(TRUE)
}

Peer Feedback
Mini-Project Peer Feedback
Use the following function to give peer feedback on mini-projects after the instructor publishes the peer feedback assignment file in the submission repository.

mp_pf_perform &lt;- function(N, github = gitcreds::gitcreds_get()$username, secret){
    if(!require("gitcreds")) install.packages("gitcreds")
    if(!require("yaml")) install.packages("yaml"); library(yaml)
    if(!require("gh")) install.packages("gh"); library(gh)
    if(!require("tidyverse")) install.packages("tidyverse"); library(tidyverse)
    if(!require("rvest")) install.packages("rvest"); library(rvest)
    if(!require("glue")) install.packages("glue"); library(glue)
    if(!require("httr2")) install.packages("httr2"); library(httr2)

    if(packageVersion("dplyr") &lt; package_version("1.2.0")){
        stop("This feedback script requires dplyr version 1.2.0 or later. Please run `update.packages()` to ensure you have the latest version of all packages.")
    }

    `%not.in%` &lt;- Negate(`%in%`)

    if(missing(N)){
        repeat{
            N &lt;- readline("Which Mini-Project peer feedback would you like to perform? [Control-C to abort] ")

            if(N %in% c("0", "1", "2", "3", "4")){
                N &lt;- as.integer(N)
                break
            }
        }
    }

    if(N %not.in% 0:4){
        stop(glue("Unknown Mini-Project Number ({N}) - Peer Feedback aborted!"))
    }

    variables &lt;- read_yaml("https://raw.githubusercontent.com/michaelweylandt/STA9750/refs/heads/main/_variables.yml")
    course_repo  &lt;- variables$course$repo
    course_short &lt;- variables$course$short

    if(basename(getwd()) != course_repo){
        stop(glue("This function should be run in your {course_repo} project folder - abort!"))
    }

    pf_file &lt;- read_yaml(glue("https://raw.githubusercontent.com/michaelweylandt/{course_repo}/refs/heads/main/pf_mp0{N}.yaml"))

    if(pf_file$mp_number != N){
        stop("Posted MP number does not match user submission - abort!")
    }

    pf_file$issue_status &lt;- pf_file |&gt;
        pluck("issue_status") |&gt;
        map(data.frame) |&gt;
        bind_rows()

    if(missing(github)){
        repeat{
            github &lt;- readline("What is your GitHub ID? ")
            if(askYesNo(glue("Please confirm: is {github} your GitHub ID? "))) break
        }
    }

    assigned_students &lt;- names(pf_file$assignments)

    if((github != tolower(github)) & (tolower(github) %in% assigned_students)){
        msg &lt;- glue("I was unable to find peer feedback for {github}, but I found an assignment for {tolower(github)}. Is this you?")
        if(askYesNo(msg)){
            github &lt;- tolower(github)
        }
    }

    if(github %not.in% assigned_students){
        stop("I was unable to find a peer feedback assignment for you. If you believe you submitted the assignment on GitHub on time, please contact the instructor for support.")
    }

    assigned_issues_encoded &lt;- pf_file |&gt; pluck("assignments", github)

    if(length(assigned_issues_encoded) != pf_file$number_of_peers){
        stop(glue("I expected {pf_file$number_of_peers} peer feedback assignments, but found {length(assigned_issues_encoded)} instead - abort!"))
    }

    if(missing(secret)){
        repeat{
            secret &lt;- readline("What is your secret phrase? [Note that your secret phrase is case-sensitive] ")
            if(askYesNo(glue("Please confirm: is {secret} your secret phrase? "))) break
        }
    }

    assigned_issues_decoded &lt;- integer(length(assigned_issues_encoded))

    for(ix in seq_along(assigned_issues_encoded)){
        n_encoded &lt;- assigned_issues_encoded[[ix]]
        secret_char &lt;- str_sub(secret, start=ix+N, end=ix+N)

        if(is.na(n_encoded) | (n_encoded == "NA")){
            n_decoded &lt;- NA_integer_
        } else {
            n_decoded &lt;- bitwXor(n_encoded, utf8ToInt(secret_char))
        }

        assigned_issues_decoded[[ix]] &lt;- n_decoded
    }

    assigned_issues_decoded_as_int &lt;- na.omit(assigned_issues_decoded)
    if(any(assigned_issues_decoded_as_int %not.in% pf_file$issue_status$number)){
        stop("Something went wrong in the decoding process.\n  Please check your secret phrase and try again.")
    }

    outfile &lt;- file.path(getwd(), glue("pf_mp0{N}_{github}.bspf"))
    mp_url &lt;- glue("https://michael-weylandt.com/STA9750/mini/mini0{N}.html")
    offer_edit &lt;- FALSE

    if(file.exists(outfile)){
        if(askYesNo(glue("I found a partially completed peer feedback file at {outfile}.\nShould I delete that and start from scratch?"))){
            if(askYesNo("Are you sure you want to delete all of your prior feedback?\nThis cannot be undone. ")){
                unlink(outfile)
            }

        } else {
            cat("Ok! I will load your old feedback.\n")
            offer_edit &lt;- askYesNo("Would you like to go back to edit older comments?\n(If 'No', I will resume where you left off.)", default=FALSE)
        }
    }

    if(N &gt; 0){
        mp_rubric &lt;- read_html(mp_url) |&gt; html_element("#mp_rubric") |&gt; html_table()
    } else {
        mp_rubric &lt;- data.frame()
    }

    INDIVIDUAL_FEEDBACK &lt;- list(
        issue_number = NA_integer_,
        issue_owner = NA_character_,
        issue_ok = NA,
        issue_status = NA_character_,
        overall_comments = list(
            positive = NA_character_,
            negative = NA_character_,
            advice = NA_character_
        ),
        scores = list(),
        mp_number = N
    )

    if(NROW(mp_rubric) &gt; 0){
        new_scores &lt;- rep(list(list(score=NA_integer_,
                                    comment=NA_character_)),
                          NROW(mp_rubric) + 1) |&gt;
            set_names(c(mp_rubric$`Course Element`), "Extra Credit")
        INDIVIDUAL_FEEDBACK[["scores"]] &lt;- new_scores

        AUTO_10_ELEMENTS &lt;- read_html(mp_url) |&gt; 
            html_element("#mp_rubric_auto") |&gt; 
            html_text2() |&gt; 
            str_split(";") |&gt; 
            pluck(1)

    } else {
        cat(glue("No rubric found for MP#0{N}, so only requesting overall comments.\nIf this seems incorrect, please abort and contact the instructor.\n"), "\n\n")
    }

    if(file.exists(outfile)){
        ALL_FEEDBACK &lt;- read_yaml(outfile)
    } else {
        ALL_FEEDBACK &lt;- rep(list(INDIVIDUAL_FEEDBACK), pf_file$number_of_peers) |&gt;
            set_names(paste0("peer_feedback_assignment_",
                             seq_along(assigned_issues_decoded)))
        ALL_FEEDBACK["evaluator"] &lt;- github
    }


    if(askYesNo("Would you like me to open the MP instructions for this submission?")){
        browseURL(glue("https://michael-weylandt.com/STA9750/mini/mini0{N}.html"))
    }

    for(assignment_ix in seq_along(assigned_issues_decoded)){
        issue_num &lt;- assigned_issues_decoded[assignment_ix]

        if(is.na(issue_num)) next

        issue_dfr &lt;- pf_file$issue_status |&gt; filter(number == issue_num)

        pluck(ALL_FEEDBACK, assignment_ix, "issue_number") &lt;- issue_num
        pluck(ALL_FEEDBACK, assignment_ix, "issue_owner") &lt;- issue_dfr |&gt; pluck("owner")
        pluck(ALL_FEEDBACK, assignment_ix, "issue_ok") &lt;- issue_dfr |&gt; pluck("ok")
        pluck(ALL_FEEDBACK, assignment_ix, "issue_status") &lt;- issue_dfr |&gt; pluck("status_oneline")

        cat(glue("Peer Feedback #0{assignment_ix} - Issue #{issue_num} ({issue_dfr |&gt; pluck('owner')})"), "\n")

        if(length(issue_dfr$ok) != 1){
            stop("Multiple statuses identified - abort!")
        }

        if(issue_dfr$ok){
            cat("- ✅ Submission passed all automated checks without problems.\n")
        } else {
            cat(glue("- ❌ Submission failed automated checks with the following message: {issue_dfr$status_oneline}\n"))
        }

        readline("Hit enter to begin peer feedback. ")

        if(askYesNo("Would you like me to open the rendered HTML for this submission", default = TRUE)){
            if(N == 0){
                browseURL(glue("https://{issue_dfr |&gt; pluck('owner')}.github.io/{course_repo}/"))
            } else {
                browseURL(glue("https://{issue_dfr |&gt; pluck('owner')}.github.io/{course_repo}/mp0{N}.html"))
            }
        }

        if(askYesNo("Would you like me to open the source qmd for this submission", default = FALSE)){
            if(N == 0){
                browseURL(glue("https://github.com/{issue_dfr |&gt; pluck('owner')}/{course_repo}/blob/{issue_dfr |&gt; pluck('branch')}/index.qmd"))
            } else {
                browseURL(glue("https://github.com/{issue_dfr |&gt; pluck('owner')}/{course_repo}/blob/{issue_dfr |&gt; pluck('branch')}/mp0{N}.qmd"))
            }
        }

        if(askYesNo("Would you like me to open the GitHub issue for this submission", default = FALSE)){
            browseURL(glue("https://github.com/michaelweylandt/{course_repo}/issues/{issue_num}"))
        }

        cat("Please review the submission carefully and return here to provide peer feedback comments.\n")
        readline("Hit enter to continue. ")

        if(NROW(mp_rubric)){
            for(rubric_row in seq_len(NROW(mp_rubric))){
                rubric_element &lt;- mp_rubric[[rubric_row, "Course Element"]]
                current_values &lt;- pluck(ALL_FEEDBACK, assignment_ix, "scores", rubric_element)

                if(!is.na(current_values$comment)){
                    if(!offer_edit) next

                    cat(glue("You previously wrote:\n\n{current_values$comment}\n\nand gave a score of {current_values$score} for {rubric_element}.\n"))

                    if(!askYesNo("Would you like to change your score or comment?", default=FALSE)){
                        next
                    }
                }

                cat(glue("Rubric Element #{rubric_row} {rubric_element}"))
                element_score &lt;- -1

                if(all(!is.na(AUTO_10_ELEMENTS)) & (rubric_element %in% AUTO_10_ELEMENTS)){
                    cat("\n")
                    cat(glue("By default, a score of 10/10 is given for {rubric_element} on this assignment."))
                    if(askYesNo("Should an automatic 10/10 be given? (Say 'no' if there are reasons a lower score should be assigned.) ")){
                        element_score &lt;- 10
                        pluck(ALL_FEEDBACK, assignment_ix, "scores", rubric_element) &lt;- list(
                            score=element_score,
                            comment="DEFAULT SCORE"
                        )
                        writeLines(as.yaml(ALL_FEEDBACK), outfile)

                        next
                    }
                }

                repeat{
                    element_score &lt;- readline(glue("On a scale of 0 to 10, what score would you give this submission for {rubric_element}? "))

                    element_score &lt;- as.numeric(element_score)

                    if(anyNA(element_score) | (element_score &gt; 10) | (element_score &lt; 0)){
                        cat("I'm sorry, I couldn't understand that score. Please try again.\n")
                    } else {
                        col_range_ix &lt;- case_when(
                            element_score &gt;= 9 ~ 2,
                            element_score &gt;= 7 ~ 3,
                            element_score &gt;= 5 ~ 4,
                            element_score &gt;= 3 ~ 5,
                            element_score &gt;= 1 ~ 6,
                            element_score == 0 ~ NA,
                            .unmatched = "error"
                        )

                        if(anyNA(col_range_ix)){
                            if(askYesNo(glue("Please confirm that the submission should get a 0 for {rubric_element}. "), default=TRUE)){
                                break
                            }
                        } else {
                            cat(glue("A score of {element_score} corresponds to a range of {colnames(mp_rubric)[col_range_ix]}"),
                                "\n",
                                "with a description of:\n\n",
                                str_wrap(mp_rubric[[rubric_row,col_range_ix]]))

                            if(askYesNo(glue("Please confirm that the submission should get a {element_score} for {rubric_element}. "), default=TRUE)){
                                break
                            }
                        }

                    }
                }

                repeat{
                    score_comment &lt;- readline("Why did you give that score? ")

                    if(nchar(score_comment)) break
                    cat("Sorry. I couldn't understand that. Try again.\n")
                }

                pluck(ALL_FEEDBACK, assignment_ix, "scores", rubric_element) &lt;- list(
                    score=element_score,
                    comment=score_comment)


                writeLines(as.yaml(ALL_FEEDBACK), outfile)
            }

            request_ec &lt;- TRUE
            current_values &lt;- pluck(ALL_FEEDBACK, assignment_ix, "scores", "Extra Credit")

            if(!is.na(current_values$comment)){
                if(!offer_edit){request_ec &lt;- FALSE}

                cat(glue("You previously wrote:\n\n{current_values$comment}\n\nand gave a score of {current_values$score} for Extra Credit.\n"))

                request_ec &lt;- askYesNo("Would you like to change your score or comment?", default=FALSE)
            }


            if(request_ec){
                readline("Please review the optional extra credit portions of the assignment. ")

                repeat{
                    ec &lt;- readline("How much extra credit should be assigned to this submission? ")

                    ec_score &lt;- as.numeric(ec)

                    if(anyNA(ec_score) | (ec_score &lt; 0)){
                        cat("I'm sorry, I couldn't understand that score. Please try again.\n")
                    } else {
                        break
                    }
                }

                ec_comment &lt;- readline(glue("Why are you awarding {ec_score} points of extra credit? "))

                pluck(ALL_FEEDBACK, assignment_ix, "scores", "Extra Credit") &lt;- list(
                    score=ec_score,
                    comment=ec_comment)


                writeLines(as.yaml(ALL_FEEDBACK), outfile)
            }

            readline("Hit enter to continue to overall / big-picture comments. ")
        }

        ### Positive Feedback
        request_positive &lt;- TRUE
        current_positive &lt;- pluck(ALL_FEEDBACK, assignment_ix, "overall_comments", "positive")

        if(!is.na(current_positive)){
            if(!offer_edit){request_ec &lt;- FALSE}

            cat(glue("For strengths, you previously wrote:\n\n{current_positive}\n\n"))

            request_positive &lt;- askYesNo("Would you like to change your comment?", default=FALSE)
        }

        if(request_positive){
            positive_comments &lt;- readline("What was one notable strength of the submission? ")

            repeat{
                positive_txt &lt;- readline("Are there any other strengths worth pointing out? [Leave blank to continue] ")

                if(nchar(positive_txt)){
                    positive_comments &lt;- c(positive_comments, positive_txt)
                } else {
                    break
                }
            }

            pluck(ALL_FEEDBACK, assignment_ix, "overall_comments", "positive") &lt;- paste(positive_comments, collapse="\n")

            writeLines(as.yaml(ALL_FEEDBACK), outfile)
        }

        ## Negative Feedback
        request_negative &lt;- TRUE
        current_negative &lt;- pluck(ALL_FEEDBACK, assignment_ix, "overall_comments", "negative")

        if(!is.na(current_negative)){
            if(!offer_edit){request_negative &lt;- FALSE}

            cat(glue("For weaknesses, you previously wrote:\n\n{current_negative}\n\n"))

            request_negative &lt;- askYesNo("Would you like to change your comment?", default=FALSE)
        }

        if(request_negative){
            negative_comments &lt;- readline("What was one area where the submission could be improved? ")

            repeat{
                negative_txt &lt;- readline("Are there any other areas that need to be improved? [Leave blank to continue] ")

                if(nchar(negative_txt)){
                    negative_comments &lt;- c(negative_comments, negative_txt)
                } else {
                    break
                }
            }

            pluck(ALL_FEEDBACK, assignment_ix, "overall_comments", "negative") &lt;- paste(negative_comments, collapse="\n")

            writeLines(as.yaml(ALL_FEEDBACK), outfile)
        }

        ## Advice Feedback
        request_advice &lt;- TRUE
        current_advice &lt;- pluck(ALL_FEEDBACK, assignment_ix, "overall_comments", "advice")

        if(!is.na(current_advice)){
            if(!offer_edit){request_advice &lt;- FALSE}

            cat(glue("For advice, you previously wrote:\n\n{current_advice}\n\n"))

            request_advice &lt;- askYesNo("Would you like to change your comment?", default=FALSE)
        }

        if(request_advice){
            advice_comments &lt;- readline("What concrete steps could be taken to improve the submission? ")

            repeat{
                advice_txt &lt;- readline("Do you have any additional advice for this classmate? [Leave blank to continue] ")

                if(nchar(advice_txt)){
                    advice_comments &lt;- c(advice_comments, advice_txt)
                } else {
                    break
                }
            }

            pluck(ALL_FEEDBACK, assignment_ix, "overall_comments", "advice") &lt;- paste(advice_comments, collapse="\n")

            writeLines(as.yaml(ALL_FEEDBACK), outfile)
        }

        writeLines(as.yaml(ALL_FEEDBACK), outfile)
    }

    cat("Thank you for your peer feedback!\n")
    cat(glue("Please submit the file {outfile}\non Brightspace to complete the peer feedback cycle"), "\n")
    cat("Do not upload this file to GitHub! Feel free to delete or move it\nafter loading to Brightspace and confirming your submission")

    if(askYesNo("Would you like me to open the peer feedback file so you can make any final edits?", default=FALSE)){
        file.edit(outfile)
        readline("Make sure to save your edits before submission. ")
    }

    readline("Hit enter to conclude peer feedback. ")

    invisible(outfile)
}

Group Project Peer Evaluations
The following script is used to provide peer feedback at the mid-point and end-point of the group project:

project_peer_evals &lt;- function(github = gitcreds::gitcreds_get()$username,
                               cycle=c("mid", "final")){
    if(!require("gitcreds")) install.packages("gitcreds")
    if(!require("yaml")) install.packages("yaml"); library(yaml)
    if(!require("gh")) install.packages("gh"); library(gh)
    if(!require("tidyverse")) install.packages("tidyverse"); library(tidyverse)
    if(!require("rvest")) install.packages("rvest"); library(rvest)
    if(!require("glue")) install.packages("glue"); library(glue)
    if(!require("httr2")) install.packages("httr2"); library(httr2)

    if(packageVersion("dplyr") &lt; package_version("1.2.0")){
        stop("This feedback script requires dplyr version 1.2.0 or later. Please run `update.packages()` to ensure you have the latest version of all packages.")
    }

    cycle &lt;- match.arg(cycle)

    safe_cycle = switch(cycle,
                        mid="mid_semester",
                        final="final")

    variables &lt;- read_yaml("https://raw.githubusercontent.com/michaelweylandt/STA9750/refs/heads/main/_variables.yml")
    course_repo  &lt;- variables$course$repo
    course_short &lt;- variables$course$short

    if(basename(getwd()) != course_repo){
        stop(glue("This function should be run in your {course_repo} project folder - abort!"))
    }

    team_file &lt;- read_yaml(glue("https://raw.githubusercontent.com/michaelweylandt/{course_repo}/refs/heads/main/{safe_cycle}_peers.yaml"))

    if(missing(github)){
        repeat{
            github &lt;- readline("What is your GitHub ID? ")
            if(askYesNo(glue("Please confirm: is {github} your GitHub ID? "))) break
        }
    }

    team_table &lt;- imap(team_file, \(x, y) data.frame(.team=y, .github=x)) |&gt; 
        bind_rows()

    all_teams &lt;- team_table |&gt; pluck(".team") |&gt; unique()
    all_github &lt;- team_table |&gt; pluck(".github") |&gt; unique()

    if((github != tolower(github)) & (tolower(github) %in% all_github)){
        msg &lt;- glue("I was unable to find peer feedback for {github}, but I found an assignment for {tolower(github)}. Is this you?")
        if(askYesNo(msg)){
            github &lt;- tolower(github)
        }
    }

    `%not.in%` &lt;- Negate(`%in%`)

    if(github %not.in% all_github){
        stop("I was unable to find a peer feedback assignment for you. If you believe you submitted the assignment on GitHub on time, please contact the instructor for support.")
    }

    team &lt;- team_table |&gt; filter(.github == github) |&gt; pull(.team)

    if(!askYesNo(glue("I think you are on team {team}. Is this correct?"))){
        stop("Did not identify correct team. Aborting!")
    }

    team_other_github &lt;- team_table |&gt; 
        filter(.team == team) |&gt; 
        filter_out(.github == github) |&gt; 
        pull(.github) |&gt; 
        sort()

    cat(glue("You are being asked to provide feedback on {length(team_other_github)} teammates:"), "\n")
    cat(paste0("- ", seq_along(team_other_github), ". ", team_other_github), sep="\n")

    if(!askYesNo("Does this look correct?")){
        stop("User error reported. Aborting!")
    }

    outfile &lt;- file.path(getwd(), glue("pf_{cycle}_{github}.bspf"))
    offer_edit &lt;- FALSE

    if(file.exists(outfile)){
        if(askYesNo(glue("I found a partially completed peer feedback file at {outfile}.\nShould I delete that and start from scratch?"))){
            if(askYesNo("Are you sure you want to delete all of your prior feedback?\nThis cannot be undone. ")){
                unlink(outfile)
            }

        } else {
            cat("Ok! I will load your old feedback.\n")
            offer_edit &lt;- askYesNo("Would you like to go back to edit older comments?\n(If 'No', I will resume where you left off.)", default=FALSE)
        }
    }

    template &lt;- "On a scale of 1 (lowest) to 5 (highest), how would you evaluate {teammate}'s {question}?"

    if(cycle == "mid"){
        project_questions &lt;- c(OQ = "Contribution(s) to Overarching Question Development", 
                               SQ = "Contribution(s) to Specific Question Development", 
                               DS = "Contribution(s) to Data Source Identification",
                               RR = "Responsibility and Reliability as a Teammate",
                               PR = "Contribution(s) to your Group Project Presentations (so far)")
    } else if(cycle == "final"){
        project_questions &lt;- c(OQ = "Contribution(s) to Overarching Question Development", 
                               SQ = "Contribution(s) to Specific Question Development", 
                               DS = "Contribution(s) to Data Source Identification",
                               DC = "Contribution(s) to Data Import and Data Cleaning",
                               IN = "Contribution(s) to Integrating Findings from Individual SQs",
                               IR = "Ability to complete their Individual Report on time and at an expected level of quality",
                               FR = "Contribution(s) to Writing the Final Report",
                               PR = "Contribution(s) to your Group Project Presentations", 
                               HP = "Willingness to help others with technical challenges", 
                               RR = "Responsibility and Reliability as a Teammate")
    } else {
        stop(glue("Unknown cycle: {cycle} - abort!"))
    }

    n_questions &lt;- length(project_questions)
    n_peers &lt;- length(team_other_github)

    INDIVIDUAL_FEEDBACK &lt;- list(
        evaluator = github, 
        teammate = NA_character_, 
        n_questions = n_questions, 
        questions = set_names(rep(list(NA_character_), n_questions), 
                           names(project_questions)),
        overall_comments = list(
            positive = NA_character_,
            negative = NA_character_,
            advice = NA_character_, 
            instructor = NA_character_
        ),
        cycle = cycle
    )

    if(file.exists(outfile)){
        ALL_FEEDBACK &lt;- read_yaml(outfile)
    } else {
        ALL_FEEDBACK &lt;- rep(list(INDIVIDUAL_FEEDBACK), n_peers)
        names(ALL_FEEDBACK) &lt;- team_other_github
        ALL_FEEDBACK["evaluator"] &lt;- github
    }

    for(teammate_ix in seq_along(team_other_github)){
        teammate &lt;- team_other_github[teammate_ix]

        if(!is.na(ALL_FEEDBACK[[teammate_ix]]$teammate)){
            if((ALL_FEEDBACK[[teammate_ix]]$teammate) != teammate){
                stop("BSPF File out of Alignment!")
            }
        }

        pluck(ALL_FEEDBACK, teammate_ix, "teammate") &lt;- teammate

        readline(glue("Hit enter to begin peer feedback for {teammate}. "))

        for(q_ix in seq_along(project_questions)){
            question &lt;- project_questions[q_ix]

            q_old_answer &lt;- pluck(ALL_FEEDBACK, teammate_ix, "questions", q_ix)

            if(!is.na(q_old_answer)){
                cat(glue("You previously gave {teammate} a score of {q_old_answer} (of 5) for {question}."), "\n")
                if(!askYesNo("Would you like to change the score you assigned?", default=FALSE)){
                    next
                }
            }

            repeat {
                cat(glue(template), "\n")
                q_answer &lt;- readline("Enter a number 1 to 5 (inclusive): ")

                q_answer &lt;- as.integer(q_answer)

                if(is.na(q_answer)){
                    cat("No comments here - you will have a chance to provide comments later. Trying again.\n")
                } else if((q_answer &lt; 1) | (q_answer &gt; 5)){
                    cat(glue("Your score must be between 1 and 5 - you gave a score of {q_answer}."), "\n")
                } else {
                    pluck(ALL_FEEDBACK, teammate_ix, "questions", q_ix) &lt;- q_answer
                    writeLines(as.yaml(ALL_FEEDBACK), outfile)
                    break
                }
            }
        }

        cat("Now it's time to give specific comments.\n")

        ### Positive Feedback
        request_positive &lt;- TRUE
        current_positive &lt;- pluck(ALL_FEEDBACK, teammate_ix, "overall_comments", "positive")

        if(!is.na(current_positive)){
            if(!offer_edit){request_ec &lt;- FALSE}

            cat(glue("For positive feedback, you previously wrote:\n\n{current_positive}\n\n"))

            request_positive &lt;- askYesNo("Would you like to change your comment?", default=FALSE)
        }

        if(request_positive){
            positive_comments &lt;- readline(glue("What is one notable strength of {teammate} as a teammate? "))

            repeat{
                positive_txt &lt;- readline("Are there any other strengths worth pointing out? [Leave blank to continue] ")

                if(nchar(positive_txt)){
                    positive_comments &lt;- c(positive_comments, positive_txt)
                } else {
                    break
                }
            }

            pluck(ALL_FEEDBACK, teammate_ix, "overall_comments", "positive") &lt;- paste(positive_comments, collapse="\n")

            writeLines(as.yaml(ALL_FEEDBACK), outfile)
        }

        ## Negative Feedback
        request_negative &lt;- TRUE
        current_negative &lt;- pluck(ALL_FEEDBACK, teammate_ix, "overall_comments", "negative")

        if(!is.na(current_negative)){
            if(!offer_edit){request_negative &lt;- FALSE}

            cat(glue("For negative feedback, you previously wrote:\n\n{current_negative}\n\n"))

            request_negative &lt;- askYesNo("Would you like to change your comment?", default=FALSE)
        }

        if(request_negative){
            negative_comments &lt;- readline(glue("What is the most challenging part of working with of {teammate} as a teammate? "))

            repeat{
                negative_txt &lt;- readline("Are there any other areas that need to be improved? [Leave blank to continue] ")

                if(nchar(negative_txt)){
                    negative_comments &lt;- c(negative_comments, negative_txt)
                } else {
                    break
                }
            }

            pluck(ALL_FEEDBACK, teammate_ix, "overall_comments", "negative") &lt;- paste(negative_comments, collapse="\n")

            writeLines(as.yaml(ALL_FEEDBACK), outfile)
        }

        ## Advice Feedback
        request_advice &lt;- TRUE
        current_advice &lt;- pluck(ALL_FEEDBACK, teammate_ix, "overall_comments", "advice")

        if(!is.na(current_advice)){
            if(!offer_edit){request_advice &lt;- FALSE}

            cat(glue("You previously gave the following advice:\n\n{current_advice}\n\n"))

            request_advice &lt;- askYesNo("Would you like to change your comment?", default=FALSE)
        }

        if(request_advice){
            advice_comments &lt;- readline(glue("What is one concrete step {teammate} could take to be a better a teammate? "))

            repeat{
                advice_txt &lt;- readline("Do you have any additional advice for this classmate? [Leave blank to continue] ")

                if(nchar(advice_txt)){
                    advice_comments &lt;- c(advice_comments, advice_txt)
                } else {
                    break
                }
            }

            pluck(ALL_FEEDBACK, teammate_ix, "overall_comments", "advice") &lt;- paste(advice_comments, collapse="\n")

            writeLines(as.yaml(ALL_FEEDBACK), outfile)
        }


        ## Instructor Comment
        request_instructor &lt;- TRUE
        current_instructor &lt;- pluck(ALL_FEEDBACK, teammate_ix, "overall_comments", "instructor")

        if(!is.na(current_instructor)){
            if(!offer_edit){request_instructor &lt;- FALSE}

            cat(glue("You previously wrote the following confidential comments to the instructor:\n\n{current_advice}\n\n"))

            request_instructor &lt;- askYesNo("Would you like to change your comment?", default=FALSE)
        }

        if(request_instructor){
            instructor_comments &lt;- readline(glue("Do you have any other comments on {teammate} you would like to confidentially share with the instructor? "))

            repeat{
                instructor_txt &lt;- readline("Do you have any additional comments for this classmate? [Leave blank to continue] ")

                if(nchar(instructor_txt)){
                    instructor_comments &lt;- c(instructor_comments, instructor_txt)
                } else {
                    break
                }
            }

            pluck(ALL_FEEDBACK, teammate_ix, "overall_comments", "instructor") &lt;- paste(instructor_comments, collapse="\n")

            writeLines(as.yaml(ALL_FEEDBACK), outfile)
        }

        writeLines(as.yaml(ALL_FEEDBACK), outfile)
    }

    cat("Thank you for your peer feedback!\n")
    cat(glue("Please submit the file {outfile}\non Brightspace to complete the peer feedback cycle"), "\n")
    cat("Do not upload this file to GitHub! Feel free to delete or move it\nafter loading to Brightspace and confirming your submission")

    readline("Hit enter to conclude peer feedback. ")

    invisible(outfile)
}

Count Words
The following script can be used to count words on a Quarto-generated web page.

count_words &lt;- function(url){
    library(rvest)
    library(stringi)

    # Note that this includes code inside an inline block, but omits
    # full-sized code blocks
    read_html(url) |&gt;
        html_elements("main p") |&gt;
        html_text() |&gt;
        stri_count_words() |&gt;
        sum()
}

Lint Submission
The following will automatically run the lintr package on a submitted qmd document.

lint_submission &lt;- function(N, peer_id){
    if(!require("yaml")) install.packages("yaml"); library(yaml)
    if(!require("gh")) install.packages("gh"); library(gh)
    if(!require("tidyverse")) install.packages("tidyverse"); library(tidyverse)
    if(!require("rvest")) install.packages("rvest"); library(rvest)
    if(!require("glue")) install.packages("glue"); library(glue)
    if(!require("lintr")) install.packages("lintr"); library(lintr)
    if(!require("httr2")) install.packages("httr2"); library(httr2)

    if(missing(N)){
        N &lt;- menu(title="Which Mini-Project submission would you like to lint?", 
                  choices=c(1, 2, 3, 4))
    }

    if(missing(peer_id)){
        peer_id &lt;- readline("What is your Peer's GitHub ID? ")
    }

    variables &lt;- read_yaml("https://raw.githubusercontent.com/michaelweylandt/STA9750/refs/heads/main/_variables.yml")
    course_repo  &lt;- variables$course$repo
    course_short &lt;- variables$course$short

    raw_url &lt;- glue("https://raw.githubusercontent.com/{peer_id}/{course_repo}/refs/heads/main/mp0{N}.qmd")

    cat("Attempting to access qmd source at", raw_url, ".\n")

    resp &lt;- request(raw_url) |&gt; 
        req_error(is_error = \(r) FALSE) |&gt;
        req_perform()

    if(resp_is_error(resp)){
        cat("I could not access the raw qmd document. Attempting to open in browser...\n")
        browseURL(resp)
        return(FALSE)
    } else {
        cat("I was able to access the raw qmd document. Beginning to lint.\n")

        tf &lt;- tempfile(pattern=glue("mp0{N}_{peer_id}_lint_document.qmd"))

        writeLines(resp_body_string(resp), tf)

        lintr::lint(tf)
    }
}

FAQ: ? Symbol (Quantifiers)
Quantifiers (multiple matches):

.{a, b}: anywhere from a to b copies (inclusive)
.{, b}: no more than b copies
.{a,}: at least a copies
.?: zero-or-one, same as .{0,1}
